################################################################################
# Adaptive Rejection Sampling (ARS) Implementation
# Based on Gilks & Wild (1992)
# 
# Main function: ars() - samples from log-concave densities
# Test function: test() - formal testing with known distributions
################################################################################

################################################################################
# AUXILIARY FUNCTIONS - Modular components for discrete tasks
################################################################################

#' Initialize abscissae points for ARS
#' @param func Log-density function (vectorized)
#' @param domain Vector of length 2 specifying the domain [lower, upper]
#' @param n_init Number of initial points
#' @return List with x (abscissae), h (log-density), and dh (derivatives)
initialize_abscissae <- function(func, domain, n_init = 10) {
  # Generate initial points within domain
  lower <- domain[1]
  upper <- domain[2]

  # Handle infinite bounds
  if (is.infinite(lower) && is.infinite(upper)) {
    x <- seq(-4, 4, length.out = n_init)
  } else if (is.infinite(lower)) {
    x <- c(upper - (1:n_init) * 2, upper - 0.1)
  } else if (is.infinite(upper)) {
    x <- c(lower + 0.1, lower + (1:n_init) * 2)
  } else {
    # Finite domain - place points within bounds
    epsilon <- (upper - lower) * 0.01
    x <- seq(lower + epsilon, upper - epsilon, length.out = n_init)
  }

  # Compute log-density
  h <- func(x)

  # Compute numerical derivatives
  dh <- compute_derivatives(func, x, h)

  list(x = x, h = h, dh = dh)
}

#' Compute numerical derivatives of log-density
#' @param func Log-density function
#' @param x Points at which to compute derivatives
#' @param h Log-density values at x (optional, for efficiency)
#' @return Vector of derivative values
compute_derivatives <- function(func, x, h = NULL) {
  if (is.null(h)) {
    h <- func(x)
  }

  n <- length(x)
  dh <- numeric(n)
  epsilon <- 1e-6

  for (i in 1:n) {
    # Use central difference for interior points
    h_plus <- func(x[i] + epsilon)
    h_minus <- func(x[i] - epsilon)
    dh[i] <- (h_plus - h_minus) / (2 * epsilon)
  }

  return(dh)
}

#' Check log-concavity at new point
#' @param x_new New point to check
#' @param h_new Log-density at new point
#' @param x Existing abscissae
#' @param h Log-density at existing abscissae
#' @param dh Derivatives at existing abscissae
#' @return TRUE if log-concave, FALSE otherwise
check_log_concavity <- function(x_new, h_new, x, h, dh) {
  # Find surrounding points
  n <- length(x)

  # Check against all line segments
  for (i in 1:(n-1)) {
    # Linear interpolation from the tangent line at x[i]
    h_upper <- h[i] + dh[i] * (x_new - x[i])

    # The log-density at x_new should be below the tangent line
    # Allow small numerical tolerance
    if (h_new > h_upper + 1e-6) {
      return(FALSE)
    }
  }

  return(TRUE)
}

#' Compute intersection points (z) of tangent lines
#' @param x Abscissae
#' @param h Log-density values
#' @param dh Derivative values
#' @return Vector of intersection points
compute_z <- function(x, h, dh) {
  n <- length(x)
  z <- numeric(n + 1)

  z[1] <- -Inf
  z[n + 1] <- Inf

  for (i in 2:n) {
    # Intersection of tangent lines at x[i-1] and x[i]
    # h[i-1] + dh[i-1]*(z - x[i-1]) = h[i] + dh[i]*(z - x[i])
    z[i] <- (h[i] - h[i-1] - x[i]*dh[i] + x[i-1]*dh[i-1]) / (dh[i-1] - dh[i])
  }

  return(z)
}

#' Evaluate upper hull at a point
#' @param x_eval Point at which to evaluate
#' @param x Abscissae
#' @param h Log-density values
#' @param dh Derivative values
#' @param z Intersection points
#' @return Upper hull value (in log scale)
eval_upper_hull <- function(x_eval, x, h, dh, z) {
  # Find which segment x_eval belongs to
  n <- length(x)

  for (i in 1:n) {
    if (x_eval >= z[i] && x_eval <= z[i+1]) {
      # Upper hull is tangent line at x[i]
      return(h[i] + dh[i] * (x_eval - x[i]))
    }
  }

  # Should not reach here
  return(-Inf)
}

#' Evaluate lower hull at a point
#' @param x_eval Point at which to evaluate
#' @param x Abscissae
#' @param h Log-density values
#' @return Lower hull value (in log scale)
eval_lower_hull <- function(x_eval, x, h) {
  n <- length(x)

  # Find surrounding points
  if (x_eval <= x[1]) {
    return(-Inf)
  }
  if (x_eval >= x[n]) {
    return(-Inf)
  }

  # Linear interpolation between surrounding abscissae
  for (i in 1:(n-1)) {
    if (x_eval >= x[i] && x_eval <= x[i+1]) {
      # Linear interpolation in log scale
      t <- (x_eval - x[i]) / (x[i+1] - x[i])
      return(h[i] * (1 - t) + h[i+1] * t)
    }
  }

  return(-Inf)
}

#' Sample from upper hull using inverse CDF method
#' @param n Number of samples
#' @param x Abscissae
#' @param h Log-density values
#' @param dh Derivative values
#' @param z Intersection points
#' @param domain Domain bounds
#' @return Vector of samples from upper hull
sample_upper_hull <- function(n, x, h, dh, z, domain) {
  n_segments <- length(x)

  # Compute normalization constant for each segment
  # Integral of exp(h[i] + dh[i]*(x - x[i])) from z[i] to z[i+1]

  segment_probs <- numeric(n_segments)

  for (i in 1:n_segments) {
    z_lower <- max(z[i], domain[1])
    z_upper <- min(z[i+1], domain[2])

    if (z_lower >= z_upper) {
      segment_probs[i] <- 0
      next
    }

    if (abs(dh[i]) < 1e-10) {
      # Nearly constant derivative - use direct integration
      segment_probs[i] <- exp(h[i]) * (z_upper - z_lower)
    } else {
      # Integration: exp(h[i] - dh[i]*x[i]) * integral(exp(dh[i]*x))
      integral <- (exp(dh[i] * z_upper) - exp(dh[i] * z_lower)) / dh[i]
      segment_probs[i] <- exp(h[i] - dh[i] * x[i]) * integral
    }
  }

  # Normalize to get probabilities
  total <- sum(segment_probs)
  if (total == 0 || !is.finite(total)) {
    stop("Upper hull normalization failed - density may not be log-concave")
  }

  segment_probs <- segment_probs / total

  # Sample segments
  segments <- sample(1:n_segments, n, replace = TRUE, prob = segment_probs)

  # Sample within each segment using inverse CDF
  samples <- numeric(n)

  for (j in 1:n) {
    i <- segments[j]
    z_lower <- max(z[i], domain[1])
    z_upper <- min(z[i+1], domain[2])

    u <- runif(1)

    if (abs(dh[i]) < 1e-10) {
      # Linear case
      samples[j] <- z_lower + u * (z_upper - z_lower)
    } else {
      # Exponential case - inverse CDF
      exp_lower <- exp(dh[i] * z_lower)
      exp_upper <- exp(dh[i] * z_upper)
      samples[j] <- log(exp_lower + u * (exp_upper - exp_lower)) / dh[i]
    }
  }

  return(samples)
}

#' Update abscissae by adding a new point
#' @param x_new New point to add
#' @param h_new Log-density at new point
#' @param dh_new Derivative at new point
#' @param x Existing abscissae
#' @param h Existing log-density values
#' @param dh Existing derivative values
#' @return Updated list with x, h, dh
update_abscissae <- function(x_new, h_new, dh_new, x, h, dh) {
  # Find insertion position
  insert_pos <- sum(x < x_new) + 1

  # Insert new values
  x <- c(x[1:(insert_pos-1)], x_new, x[insert_pos:length(x)])
  h <- c(h[1:(insert_pos-1)], h_new, h[insert_pos:length(h)])
  dh <- c(dh[1:(insert_pos-1)], dh_new, dh[insert_pos:length(dh)])

  list(x = x, h = h, dh = dh)
}

################################################################################
# MAIN ARS FUNCTION
################################################################################

#' Adaptive Rejection Sampling
#' 
#' Samples from a log-concave density using adaptive rejection sampling.
#' 
#' @param n Number of samples to generate (must be positive integer)
#' @param func Function or expression for (possibly unnormalized) log-density.
#'             Must be vectorized and log-concave.
#' @param domain Vector of length 2 specifying domain [lower, upper]. 
#'               Can use -Inf or Inf for unbounded domains.
#' @param n_init Number of initial abscissae points (default: 10)
#' 
#' @return Vector of n samples from the target distribution
#' 
#' @examples
#' # Sample from standard normal
#' samples <- ars(1000, function(x) dnorm(x, log=TRUE), c(-Inf, Inf))
#' 
#' # Sample from exponential(1)
#' samples <- ars(1000, function(x) dexp(x, log=TRUE), c(0, Inf))
ars <- function(n, func, domain = c(-Inf, Inf), n_init = 10) {

  ################################
  # INPUT VALIDATION
  ################################

  # Check n
  if (missing(n) || !is.numeric(n) || length(n) != 1) {
    stop("n must be a single numeric value")
  }
  if (n <= 0 || n != as.integer(n)) {
    stop("n must be a positive integer")
  }
  n <- as.integer(n)

  # Check func
  if (missing(func)) {
    stop("func is required")
  }
  if (!is.function(func)) {
    stop("func must be a function")
  }

  # Test that func is vectorized
  test_input <- c(0, 1)
  test_output <- tryCatch(
    func(test_input),
    error = function(e) {
      stop("func must be vectorized and accept numeric vectors")
    }
  )

  if (length(test_output) != length(test_input)) {
    stop("func must be vectorized (return same length as input)")
  }

  # Check domain
  if (!is.numeric(domain) || length(domain) != 2) {
    stop("domain must be a numeric vector of length 2")
  }
  if (domain[1] >= domain[2]) {
    stop("domain[1] must be less than domain[2]")
  }

  # Check n_init
  if (!is.numeric(n_init) || n_init < 3) {
    stop("n_init must be at least 3")
  }

  ################################
  # INITIALIZATION
  ################################

  init <- initialize_abscissae(func, domain, n_init)
  x <- init$x
  h <- init$h
  dh <- init$dh

  # Check that initial points are valid
  if (any(!is.finite(h))) {
    stop("func returned non-finite values at initial points")
  }

  ################################
  # SAMPLING LOOP
  ################################

  samples <- numeric(n)
  n_samples <- 0
  max_iterations <- n * 100  # Safety limit
  iterations <- 0

  while (n_samples < n && iterations < max_iterations) {
    iterations <- iterations + 1

    # Compute intersection points
    z <- compute_z(x, h, dh)

    # Sample from upper hull
    x_star <- sample_upper_hull(1, x, h, dh, z, domain)

    # Evaluate hulls and density at x_star
    u_star <- eval_upper_hull(x_star, x, h, dh, z)
    l_star <- eval_lower_hull(x_star, x, h)
    h_star <- func(x_star)

    # Check for non-finite density
    if (!is.finite(h_star)) {
      # Skip this sample and continue
      next
    }

    # Squeezing test (accept without evaluating density)
    w <- runif(1)

    if (log(w) <= l_star - u_star) {
      # Accept
      n_samples <- n_samples + 1
      samples[n_samples] <- x_star
    } else {
      # Rejection test
      if (log(w) <= h_star - u_star) {
        # Accept
        n_samples <- n_samples + 1
        samples[n_samples] <- x_star
      }

      # Update abscissae (whether accepted or rejected)
      # Compute derivative at x_star
      dh_star <- compute_derivatives(func, x_star, h_star)

      # Check log-concavity
      if (!check_log_concavity(x_star, h_star, x, h, dh)) {
        stop("Non-log-concave density detected at x = ", x_star)
      }

      # Add point to abscissae
      updated <- update_abscissae(x_star, h_star, dh_star, x, h, dh)
      x <- updated$x
      h <- updated$h
      dh <- updated$dh
    }
  }

  if (iterations >= max_iterations) {
    warning("Maximum iterations reached. Returning ", n_samples, " samples.")
    samples <- samples[1:n_samples]
  }

  return(samples)
}

################################################################################
# TESTING FUNCTION
################################################################################

#' Formal testing of ARS implementation
#' 
#' Tests ARS against known distributions and validates correctness.
#' Outputs clear test results with pass/fail status.
test <- function() {

  cat("\n")
  cat("========================================\n")
  cat("ARS TESTING SUITE\n")
  cat("========================================\n\n")

  # Set seed for reproducibility
  set.seed(42)

  n_samples <- 10000
  alpha <- 0.05  # Significance level for statistical tests

  ################################
  # TEST 1: Standard Normal Distribution
  ################################

  cat("TEST 1: Standard Normal Distribution\n")
  cat("--------------------------------------\n")

  tryCatch({
    samples <- ars(n_samples, function(x) dnorm(x, log=TRUE), c(-Inf, Inf))

    # Write samples to file
    write.table(samples, "/app/normal_samples.txt", row.names = FALSE, col.names = FALSE)

    sample_mean <- mean(samples)
    sample_sd <- sd(samples)

    cat(sprintf("  Generated %d samples\n", length(samples)))
    cat(sprintf("  Sample mean: %.4f (expected: 0.0000)\n", sample_mean))
    cat(sprintf("  Sample SD:   %.4f (expected: 1.0000)\n", sample_sd))

    # Statistical test: Kolmogorov-Smirnov test
    ks_result <- ks.test(samples, "pnorm")

    # Check if sample moments are reasonable
    mean_ok <- abs(sample_mean - 0) < 0.05
    sd_ok <- abs(sample_sd - 1) < 0.05
    ks_ok <- ks_result$p.value > alpha

    if (mean_ok && sd_ok && ks_ok) {
      cat("  TEST 1: PASS\n")
    } else {
      cat("  TEST 1: FAIL\n")
      if (!mean_ok) cat("    - Mean outside tolerance\n")
      if (!sd_ok) cat("    - SD outside tolerance\n")
      if (!ks_ok) cat(sprintf("    - KS test failed (p=%.4f)\n", ks_result$p.value))
    }
  }, error = function(e) {
    cat("  TEST 1: FAIL\n")
    cat(sprintf("    Error: %s\n", e$message))
  })

  cat("\n")

  ################################
  # TEST 2: Exponential Distribution
  ################################

  cat("TEST 2: Exponential(1) Distribution\n")
  cat("--------------------------------------\n")

  tryCatch({
    samples <- ars(n_samples, function(x) dexp(x, rate=1, log=TRUE), c(0, Inf))

    # Write samples to file
    write.table(samples, "/app/exponential_samples.txt", row.names = FALSE, col.names = FALSE)

    sample_mean <- mean(samples)
    sample_sd <- sd(samples)

    cat(sprintf("  Generated %d samples\n", length(samples)))
    cat(sprintf("  Sample mean: %.4f (expected: 1.0000)\n", sample_mean))
    cat(sprintf("  Sample SD:   %.4f (expected: 1.0000)\n", sample_sd))

    # Statistical test
    ks_result <- ks.test(samples, "pexp", rate=1)

    mean_ok <- abs(sample_mean - 1) < 0.05
    sd_ok <- abs(sample_sd - 1) < 0.05
    ks_ok <- ks_result$p.value > alpha

    if (mean_ok && sd_ok && ks_ok) {
      cat("  TEST 2: PASS\n")
    } else {
      cat("  TEST 2: FAIL\n")
      if (!mean_ok) cat("    - Mean outside tolerance\n")
      if (!sd_ok) cat("    - SD outside tolerance\n")
      if (!ks_ok) cat(sprintf("    - KS test failed (p=%.4f)\n", ks_result$p.value))
    }
  }, error = function(e) {
    cat("  TEST 2: FAIL\n")
    cat(sprintf("    Error: %s\n", e$message))
  })

  cat("\n")

  ################################
  # TEST 3: Gamma Distribution
  ################################

  cat("TEST 3: Gamma(3, 2) Distribution\n")
  cat("--------------------------------------\n")

  tryCatch({
    shape <- 3
    rate <- 2
    samples <- ars(n_samples, function(x) dgamma(x, shape=shape, rate=rate, log=TRUE), c(0, Inf))

    sample_mean <- mean(samples)
    sample_sd <- sd(samples)
    expected_mean <- shape / rate
    expected_sd <- sqrt(shape) / rate

    cat(sprintf("  Generated %d samples\n", length(samples)))
    cat(sprintf("  Sample mean: %.4f (expected: %.4f)\n", sample_mean, expected_mean))
    cat(sprintf("  Sample SD:   %.4f (expected: %.4f)\n", sample_sd, expected_sd))

    ks_result <- ks.test(samples, "pgamma", shape=shape, rate=rate)

    mean_ok <- abs(sample_mean - expected_mean) < 0.05
    sd_ok <- abs(sample_sd - expected_sd) < 0.05
    ks_ok <- ks_result$p.value > alpha

    if (mean_ok && sd_ok && ks_ok) {
      cat("  TEST 3: PASS\n")
    } else {
      cat("  TEST 3: FAIL\n")
      if (!mean_ok) cat("    - Mean outside tolerance\n")
      if (!sd_ok) cat("    - SD outside tolerance\n")
      if (!ks_ok) cat(sprintf("    - KS test failed (p=%.4f)\n", ks_result$p.value))
    }
  }, error = function(e) {
    cat("  TEST 3: FAIL\n")
    cat(sprintf("    Error: %s\n", e$message))
  })

  cat("\n")

  ################################
  # TEST 4: Beta Distribution (finite domain)
  ################################

  cat("TEST 4: Beta(2, 5) Distribution\n")
  cat("--------------------------------------\n")

  tryCatch({
    alpha_param <- 2
    beta_param <- 5
    samples <- ars(n_samples, function(x) dbeta(x, alpha_param, beta_param, log=TRUE), c(0, 1))

    sample_mean <- mean(samples)
    sample_sd <- sd(samples)
    expected_mean <- alpha_param / (alpha_param + beta_param)
    expected_var <- (alpha_param * beta_param) / ((alpha_param + beta_param)^2 * (alpha_param + beta_param + 1))
    expected_sd <- sqrt(expected_var)

    cat(sprintf("  Generated %d samples\n", length(samples)))
    cat(sprintf("  Sample mean: %.4f (expected: %.4f)\n", sample_mean, expected_mean))
    cat(sprintf("  Sample SD:   %.4f (expected: %.4f)\n", sample_sd, expected_sd))

    ks_result <- ks.test(samples, "pbeta", alpha_param, beta_param)

    mean_ok <- abs(sample_mean - expected_mean) < 0.05
    sd_ok <- abs(sample_sd - expected_sd) < 0.05
    ks_ok <- ks_result$p.value > alpha

    if (mean_ok && sd_ok && ks_ok) {
      cat("  TEST 4: PASS\n")
    } else {
      cat("  TEST 4: FAIL\n")
      if (!mean_ok) cat("    - Mean outside tolerance\n")
      if (!sd_ok) cat("    - SD outside tolerance\n")
      if (!ks_ok) cat(sprintf("    - KS test failed (p=%.4f)\n", ks_result$p.value))
    }
  }, error = function(e) {
    cat("  TEST 4: FAIL\n")
    cat(sprintf("    Error: %s\n", e$message))
  })

  cat("\n")

  ################################
  # TEST 5: Input Validation - Negative n
  ################################

  cat("TEST 5: Input Validation - Negative n\n")
  cat("--------------------------------------\n")

  tryCatch({
    samples <- ars(-10, function(x) dnorm(x, log=TRUE), c(-Inf, Inf))
    cat("  TEST 5: FAIL (should have thrown error)\n")
  }, error = function(e) {
    if (grepl("positive", e$message, ignore.case=TRUE)) {
      cat("  TEST 5: PASS (correctly rejected negative n)\n")
    } else {
      cat("  TEST 5: FAIL (wrong error message)\n")
    }
  })

  cat("\n")

  ################################
  # TEST 6: Input Validation - Invalid domain
  ################################

  cat("TEST 6: Input Validation - Invalid Domain\n")
  cat("--------------------------------------\n")

  tryCatch({
    samples <- ars(100, function(x) dnorm(x, log=TRUE), c(5, 1))
    cat("  TEST 6: FAIL (should have thrown error)\n")
  }, error = function(e) {
    if (grepl("domain", e$message, ignore.case=TRUE)) {
      cat("  TEST 6: PASS (correctly rejected invalid domain)\n")
    } else {
      cat("  TEST 6: FAIL (wrong error message)\n")
    }
  })

  cat("\n")

  ################################
  # TEST 7: Non-log-concave density detection
  ################################

  cat("TEST 7: Non-log-concave Density Detection\n")
  cat("--------------------------------------\n")

  tryCatch({
    # Normal mixture - not log-concave
    samples <- ars(100, function(x) {
      log(0.5 * dnorm(x, -2, 0.5) + 0.5 * dnorm(x, 2, 0.5))
    }, c(-Inf, Inf), n_init = 5)
    cat("  TEST 7: FAIL (should have detected non-log-concavity)\n")
  }, error = function(e) {
    if (grepl("log-concave", e$message, ignore.case=TRUE)) {
      cat("  TEST 7: PASS (correctly detected non-log-concave density)\n")
    } else {
      cat(sprintf("  TEST 7: FAIL (error but wrong message: %s)\n", e$message))
    }
  })

  cat("\n")

  ################################
  # TEST 8: Unnormalized density
  ################################

  cat("TEST 8: Unnormalized Density\n")
  cat("--------------------------------------\n")

  tryCatch({
    # Unnormalized normal (multiplied by constant)
    samples <- ars(n_samples, function(x) dnorm(x, log=TRUE) + log(5), c(-Inf, Inf))

    sample_mean <- mean(samples)
    sample_sd <- sd(samples)

    cat(sprintf("  Generated %d samples\n", length(samples)))
    cat(sprintf("  Sample mean: %.4f (expected: 0.0000)\n", sample_mean))
    cat(sprintf("  Sample SD:   %.4f (expected: 1.0000)\n", sample_sd))

    mean_ok <- abs(sample_mean - 0) < 0.05
    sd_ok <- abs(sample_sd - 1) < 0.05

    if (mean_ok && sd_ok) {
      cat("  TEST 8: PASS\n")
    } else {
      cat("  TEST 8: FAIL\n")
    }
  }, error = function(e) {
    cat("  TEST 8: FAIL\n")
    cat(sprintf("    Error: %s\n", e$message))
  })

  cat("\n")
  cat("========================================\n")
  cat("TESTING COMPLETE\n")
  cat("========================================\n\n")
}

################################################################################
# END OF FILE
################################################################################

################################################################################
# Adaptive Rejection Sampling (ARS) Implementation
# Based on Gilks & Wild (1992)
# 
# Main function: ars() - samples from log-concave densities
# Test function: test() - formal testing with known distributions
################################################################################

################################################################################
# AUXILIARY FUNCTIONS - Modular components for discrete tasks
################################################################################

#' Initialize abscissae points for ARS
#' @param func Log-density function (vectorized)
#' @param domain Vector of length 2 specifying the domain [lower, upper]
#' @param n_init Number of initial points
#' @return List with x (abscissae), h (log-density), and dh (derivatives)
initialize_abscissae <- function(func, domain, n_init = 10) {
  # Generate initial points within domain
  lower <- domain[1]
  upper <- domain[2]

  # Handle infinite bounds
  if (is.infinite(lower) && is.infinite(upper)) {
    x <- seq(-4, 4, length.out = n_init)
  } else if (is.infinite(lower)) {
    x <- c(upper - (1:n_init) * 2, upper - 0.1)
  } else if (is.infinite(upper)) {
    x <- c(lower + 0.1, lower + (1:n_init) * 2)
  } else {
    # Finite domain - place points within bounds
    epsilon <- (upper - lower) * 0.01
    x <- seq(lower + epsilon, upper - epsilon, length.out = n_init)
  }

  # Compute log-density
  h <- func(x)

  # Compute numerical derivatives
  dh <- compute_derivatives(func, x, h)

  list(x = x, h = h, dh = dh)
}

#' Compute numerical derivatives of log-density
#' @param func Log-density function
#' @param x Points at which to compute derivatives
#' @param h Log-density values at x (optional, for efficiency)
#' @return Vector of derivative values
compute_derivatives <- function(func, x, h = NULL) {
  if (is.null(h)) {
    h <- func(x)
  }

  n <- length(x)
  dh <- numeric(n)
  epsilon <- 1e-6

  for (i in 1:n) {
    # Use central difference for interior points
    h_plus <- func(x[i] + epsilon)
    h_minus <- func(x[i] - epsilon)
    dh[i] <- (h_plus - h_minus) / (2 * epsilon)
  }

  return(dh)
}

#' Check log-concavity at new point
#' @param x_new New point to check
#' @param h_new Log-density at new point
#' @param x Existing abscissae
#' @param h Log-density at existing abscissae
#' @param dh Derivatives at existing abscissae
#' @return TRUE if log-concave, FALSE otherwise
check_log_concavity <- function(x_new, h_new, x, h, dh) {
  # Find surrounding points
  n <- length(x)

  # Check against all line segments
  for (i in 1:(n-1)) {
    # Linear interpolation from the tangent line at x[i]
    h_upper <- h[i] + dh[i] * (x_new - x[i])

    # The log-density at x_new should be below the tangent line
    # Allow small numerical tolerance
    if (h_new > h_upper + 1e-6) {
      return(FALSE)
    }
  }

  return(TRUE)
}

#' Compute intersection points (z) of tangent lines
#' @param x Abscissae
#' @param h Log-density values
#' @param dh Derivative values
#' @return Vector of intersection points
compute_z <- function(x, h, dh) {
  n <- length(x)
  z <- numeric(n + 1)

  z[1] <- -Inf
  z[n + 1] <- Inf

  for (i in 2:n) {
    # Intersection of tangent lines at x[i-1] and x[i]
    # h[i-1] + dh[i-1]*(z - x[i-1]) = h[i] + dh[i]*(z - x[i])
    z[i] <- (h[i] - h[i-1] - x[i]*dh[i] + x[i-1]*dh[i-1]) / (dh[i-1] - dh[i])
  }

  return(z)
}

#' Evaluate upper hull at a point
#' @param x_eval Point at which to evaluate
#' @param x Abscissae
#' @param h Log-density values
#' @param dh Derivative values
#' @param z Intersection points
#' @return Upper hull value (in log scale)
eval_upper_hull <- function(x_eval, x, h, dh, z) {
  # Find which segment x_eval belongs to
  n <- length(x)

  for (i in 1:n) {
    if (x_eval >= z[i] && x_eval <= z[i+1]) {
      # Upper hull is tangent line at x[i]
      return(h[i] + dh[i] * (x_eval - x[i]))
    }
  }

  # Should not reach here
  return(-Inf)
}

#' Evaluate lower hull at a point
#' @param x_eval Point at which to evaluate
#' @param x Abscissae
#' @param h Log-density values
#' @return Lower hull value (in log scale)
eval_lower_hull <- function(x_eval, x, h) {
  n <- length(x)

  # Find surrounding points
  if (x_eval <= x[1]) {
    return(-Inf)
  }
  if (x_eval >= x[n]) {
    return(-Inf)
  }

  # Linear interpolation between surrounding abscissae
  for (i in 1:(n-1)) {
    if (x_eval >= x[i] && x_eval <= x[i+1]) {
      # Linear interpolation in log scale
      t <- (x_eval - x[i]) / (x[i+1] - x[i])
      return(h[i] * (1 - t) + h[i+1] * t)
    }
  }

  return(-Inf)
}

#' Sample from upper hull using inverse CDF method
#' @param n Number of samples
#' @param x Abscissae
#' @param h Log-density values
#' @param dh Derivative values
#' @param z Intersection points
#' @param domain Domain bounds
#' @return Vector of samples from upper hull
sample_upper_hull <- function(n, x, h, dh, z, domain) {
  n_segments <- length(x)

  # Compute normalization constant for each segment
  # Integral of exp(h[i] + dh[i]*(x - x[i])) from z[i] to z[i+1]

  segment_probs <- numeric(n_segments)

  for (i in 1:n_segments) {
    z_lower <- max(z[i], domain[1])
    z_upper <- min(z[i+1], domain[2])

    if (z_lower >= z_upper) {
      segment_probs[i] <- 0
      next
    }

    if (abs(dh[i]) < 1e-10) {
      # Nearly constant derivative - use direct integration
      segment_probs[i] <- exp(h[i]) * (z_upper - z_lower)
    } else {
      # Integration: exp(h[i] - dh[i]*x[i]) * integral(exp(dh[i]*x))
      integral <- (exp(dh[i] * z_upper) - exp(dh[i] * z_lower)) / dh[i]
      segment_probs[i] <- exp(h[i] - dh[i] * x[i]) * integral
    }
  }

  # Normalize to get probabilities
  total <- sum(segment_probs)
  if (total == 0 || !is.finite(total)) {
    stop("Upper hull normalization failed - density may not be log-concave")
  }

  segment_probs <- segment_probs / total

  # Sample segments
  segments <- sample(1:n_segments, n, replace = TRUE, prob = segment_probs)

  # Sample within each segment using inverse CDF
  samples <- numeric(n)

  for (j in 1:n) {
    i <- segments[j]
    z_lower <- max(z[i], domain[1])
    z_upper <- min(z[i+1], domain[2])

    u <- runif(1)

    if (abs(dh[i]) < 1e-10) {
      # Linear case
      samples[j] <- z_lower + u * (z_upper - z_lower)
    } else {
      # Exponential case - inverse CDF
      exp_lower <- exp(dh[i] * z_lower)
      exp_upper <- exp(dh[i] * z_upper)
      samples[j] <- log(exp_lower + u * (exp_upper - exp_lower)) / dh[i]
    }
  }

  return(samples)
}

#' Update abscissae by adding a new point
#' @param x_new New point to add
#' @param h_new Log-density at new point
#' @param dh_new Derivative at new point
#' @param x Existing abscissae
#' @param h Existing log-density values
#' @param dh Existing derivative values
#' @return Updated list with x, h, dh
update_abscissae <- function(x_new, h_new, dh_new, x, h, dh) {
  # Find insertion position
  insert_pos <- sum(x < x_new) + 1

  # Insert new values
  x <- c(x[1:(insert_pos-1)], x_new, x[insert_pos:length(x)])
  h <- c(h[1:(insert_pos-1)], h_new, h[insert_pos:length(h)])
  dh <- c(dh[1:(insert_pos-1)], dh_new, dh[insert_pos:length(dh)])

  list(x = x, h = h, dh = dh)
}

