#' Formal testing of ARS implementation
#' 
#' Tests ARS against known distributions and validates correctness.
#' Outputs clear test results with pass/fail status.
test <- function() {

  cat("\n")
  cat("========================================\n")
  cat("ARS TESTING SUITE\n")
  cat("========================================\n\n")

  # Set seed for reproducibility
  set.seed(42)

  n_samples <- 10000
  alpha <- 0.05  # Significance level for statistical tests

  ################################
  # TEST 1: Standard Normal Distribution
  ################################

  cat("TEST 1: Standard Normal Distribution\n")
  cat("--------------------------------------\n")

  tryCatch({
    samples <- ars(n_samples, function(x) dnorm(x, log=TRUE), c(-Inf, Inf))

    # Write samples to file
    write.table(samples, "/app/normal_samples.txt", row.names = FALSE, col.names = FALSE)

    sample_mean <- mean(samples)
    sample_sd <- sd(samples)

    cat(sprintf("  Generated %d samples\n", length(samples)))
    cat(sprintf("  Sample mean: %.4f (expected: 0.0000)\n", sample_mean))
    cat(sprintf("  Sample SD:   %.4f (expected: 1.0000)\n", sample_sd))

    # Statistical test: Kolmogorov-Smirnov test
    ks_result <- ks.test(samples, "pnorm")

    # Check if sample moments are reasonable
    mean_ok <- abs(sample_mean - 0) < 0.05
    sd_ok <- abs(sample_sd - 1) < 0.05
    ks_ok <- ks_result$p.value > alpha

    if (mean_ok && sd_ok && ks_ok) {
      cat("  TEST 1: PASS\n")
    } else {
      cat("  TEST 1: FAIL\n")
      if (!mean_ok) cat("    - Mean outside tolerance\n")
      if (!sd_ok) cat("    - SD outside tolerance\n")
      if (!ks_ok) cat(sprintf("    - KS test failed (p=%.4f)\n", ks_result$p.value))
    }
  }, error = function(e) {
    cat("  TEST 1: FAIL\n")
    cat(sprintf("    Error: %s\n", e$message))
  })

  cat("\n")

  ################################
  # TEST 2: Exponential Distribution
  ################################

  cat("TEST 2: Exponential(1) Distribution\n")
  cat("--------------------------------------\n")

  tryCatch({
    samples <- ars(n_samples, function(x) dexp(x, rate=1, log=TRUE), c(0, Inf))

    # Write samples to file
    write.table(samples, "/app/exponential_samples.txt", row.names = FALSE, col.names = FALSE)

    sample_mean <- mean(samples)
    sample_sd <- sd(samples)

    cat(sprintf("  Generated %d samples\n", length(samples)))
    cat(sprintf("  Sample mean: %.4f (expected: 1.0000)\n", sample_mean))
    cat(sprintf("  Sample SD:   %.4f (expected: 1.0000)\n", sample_sd))

    # Statistical test
    ks_result <- ks.test(samples, "pexp", rate=1)

    mean_ok <- abs(sample_mean - 1) < 0.05
    sd_ok <- abs(sample_sd - 1) < 0.05
    ks_ok <- ks_result$p.value > alpha

    if (mean_ok && sd_ok && ks_ok) {
      cat("  TEST 2: PASS\n")
    } else {
      cat("  TEST 2: FAIL\n")
      if (!mean_ok) cat("    - Mean outside tolerance\n")
      if (!sd_ok) cat("    - SD outside tolerance\n")
      if (!ks_ok) cat(sprintf("    - KS test failed (p=%.4f)\n", ks_result$p.value))
    }
  }, error = function(e) {
    cat("  TEST 2: FAIL\n")
    cat(sprintf("    Error: %s\n", e$message))
  })

  cat("\n")

  ################################
  # TEST 3: Gamma Distribution
  ################################

  cat("TEST 3: Gamma(3, 2) Distribution\n")
  cat("--------------------------------------\n")

  tryCatch({
    shape <- 3
    rate <- 2
    samples <- ars(n_samples, function(x) dgamma(x, shape=shape, rate=rate, log=TRUE), c(0, Inf))

    sample_mean <- mean(samples)
    sample_sd <- sd(samples)
    expected_mean <- shape / rate
    expected_sd <- sqrt(shape) / rate

    cat(sprintf("  Generated %d samples\n", length(samples)))
    cat(sprintf("  Sample mean: %.4f (expected: %.4f)\n", sample_mean, expected_mean))
    cat(sprintf("  Sample SD:   %.4f (expected: %.4f)\n", sample_sd, expected_sd))

    ks_result <- ks.test(samples, "pgamma", shape=shape, rate=rate)

    mean_ok <- abs(sample_mean - expected_mean) < 0.05
    sd_ok <- abs(sample_sd - expected_sd) < 0.05
    ks_ok <- ks_result$p.value > alpha

    if (mean_ok && sd_ok && ks_ok) {
      cat("  TEST 3: PASS\n")
    } else {
      cat("  TEST 3: FAIL\n")
      if (!mean_ok) cat("    - Mean outside tolerance\n")
      if (!sd_ok) cat("    - SD outside tolerance\n")
      if (!ks_ok) cat(sprintf("    - KS test failed (p=%.4f)\n", ks_result$p.value))
    }
  }, error = function(e) {
    cat("  TEST 3: FAIL\n")
    cat(sprintf("    Error: %s\n", e$message))
  })

  cat("\n")

  ################################
  # TEST 4: Beta Distribution (finite domain)
  ################################

  cat("TEST 4: Beta(2, 5) Distribution\n")
  cat("--------------------------------------\n")

  tryCatch({
    alpha_param <- 2
    beta_param <- 5
    samples <- ars(n_samples, function(x) dbeta(x, alpha_param, beta_param, log=TRUE), c(0, 1))

    sample_mean <- mean(samples)
    sample_sd <- sd(samples)
    expected_mean <- alpha_param / (alpha_param + beta_param)
    expected_var <- (alpha_param * beta_param) / ((alpha_param + beta_param)^2 * (alpha_param + beta_param + 1))
    expected_sd <- sqrt(expected_var)

    cat(sprintf("  Generated %d samples\n", length(samples)))
    cat(sprintf("  Sample mean: %.4f (expected: %.4f)\n", sample_mean, expected_mean))
    cat(sprintf("  Sample SD:   %.4f (expected: %.4f)\n", sample_sd, expected_sd))

    ks_result <- ks.test(samples, "pbeta", alpha_param, beta_param)

    mean_ok <- abs(sample_mean - expected_mean) < 0.05
    sd_ok <- abs(sample_sd - expected_sd) < 0.05
    ks_ok <- ks_result$p.value > alpha

    if (mean_ok && sd_ok && ks_ok) {
      cat("  TEST 4: PASS\n")
    } else {
      cat("  TEST 4: FAIL\n")
      if (!mean_ok) cat("    - Mean outside tolerance\n")
      if (!sd_ok) cat("    - SD outside tolerance\n")
      if (!ks_ok) cat(sprintf("    - KS test failed (p=%.4f)\n", ks_result$p.value))
    }
  }, error = function(e) {
    cat("  TEST 4: FAIL\n")
    cat(sprintf("    Error: %s\n", e$message))
  })

  cat("\n")

  ################################
  # TEST 5: Input Validation - Negative n
  ################################

  cat("TEST 5: Input Validation - Negative n\n")
  cat("--------------------------------------\n")

  tryCatch({
    samples <- ars(-10, function(x) dnorm(x, log=TRUE), c(-Inf, Inf))
    cat("  TEST 5: FAIL (should have thrown error)\n")
  }, error = function(e) {
    if (grepl("positive", e$message, ignore.case=TRUE)) {
      cat("  TEST 5: PASS (correctly rejected negative n)\n")
    } else {
      cat("  TEST 5: FAIL (wrong error message)\n")
    }
  })

  cat("\n")

  ################################
  # TEST 6: Input Validation - Invalid domain
  ################################

  cat("TEST 6: Input Validation - Invalid Domain\n")
  cat("--------------------------------------\n")

  tryCatch({
    samples <- ars(100, function(x) dnorm(x, log=TRUE), c(5, 1))
    cat("  TEST 6: FAIL (should have thrown error)\n")
  }, error = function(e) {
    if (grepl("domain", e$message, ignore.case=TRUE)) {
      cat("  TEST 6: PASS (correctly rejected invalid domain)\n")
    } else {
      cat("  TEST 6: FAIL (wrong error message)\n")
    }
  })

  cat("\n")

  ################################
  # TEST 7: Non-log-concave density detection
  ################################

  cat("TEST 7: Non-log-concave Density Detection\n")
  cat("--------------------------------------\n")

  tryCatch({
    # Normal mixture - not log-concave
    samples <- ars(100, function(x) {
      log(0.5 * dnorm(x, -2, 0.5) + 0.5 * dnorm(x, 2, 0.5))
    }, c(-Inf, Inf), n_init = 5)
    cat("  TEST 7: FAIL (should have detected non-log-concavity)\n")
  }, error = function(e) {
    if (grepl("log-concave", e$message, ignore.case=TRUE)) {
      cat("  TEST 7: PASS (correctly detected non-log-concave density)\n")
    } else {
      cat(sprintf("  TEST 7: FAIL (error but wrong message: %s)\n", e$message))
    }
  })

  cat("\n")

  ################################
  # TEST 8: Unnormalized density
  ################################

  cat("TEST 8: Unnormalized Density\n")
  cat("--------------------------------------\n")

  tryCatch({
    # Unnormalized normal (multiplied by constant)
    samples <- ars(n_samples, function(x) dnorm(x, log=TRUE) + log(5), c(-Inf, Inf))

    sample_mean <- mean(samples)
    sample_sd <- sd(samples)

    cat(sprintf("  Generated %d samples\n", length(samples)))
    cat(sprintf("  Sample mean: %.4f (expected: 0.0000)\n", sample_mean))
    cat(sprintf("  Sample SD:   %.4f (expected: 1.0000)\n", sample_sd))

    mean_ok <- abs(sample_mean - 0) < 0.05
    sd_ok <- abs(sample_sd - 1) < 0.05

    if (mean_ok && sd_ok) {
      cat("  TEST 8: PASS\n")
    } else {
      cat("  TEST 8: FAIL\n")
    }
  }, error = function(e) {
    cat("  TEST 8: FAIL\n")
    cat(sprintf("    Error: %s\n", e$message))
  })

  cat("\n")
  cat("========================================\n")
  cat("TESTING COMPLETE\n")
  cat("========================================\n\n")
}

################################################################################
# END OF FILE
################################################################################

