eval_upper_hull <- function(x_eval, x, h, dh, z) {
  # Find which segment x_eval belongs to
  n <- length(x)

  for (i in 1:n) {
    # Safe comparison with potentially infinite z values
    in_segment <- FALSE
    if (is.finite(x_eval) && is.finite(z[i]) && is.finite(z[i+1])) {
      in_segment <- (x_eval >= z[i] && x_eval <= z[i+1])
    } else if (is.finite(x_eval)) {
      # Handle infinite boundaries
      lower_ok <- is.infinite(z[i]) || x_eval >= z[i]
      upper_ok <- is.infinite(z[i+1]) || x_eval <= z[i+1]
      in_segment <- lower_ok && upper_ok
    }

    if (isTRUE(in_segment)) {
      # Upper hull is tangent line at x[i]
      return(h[i] + dh[i] * (x_eval - x[i]))
    }
  }

  # Should not reach here
  return(-Inf)
}

