    return(-Inf)
  }

  # Linear interpolation between surrounding abscissae
  for (i in 1:(n-1)) {
    in_range <- FALSE
    if (is.finite(x_eval) && is.finite(x[i]) && is.finite(x[i+1])) {
      in_range <- (x_eval >= x[i] && x_eval <= x[i+1])
