    }

    # The log-density at x_new should be below the tangent line
    # Use adaptive tolerance based on magnitude and extrapolation distance
    # In tails, numerical errors in dh can accumulate over large distances
    tolerance <- max(1e-4, abs(h_new) * 1e-8)
    if (h_new > h_upper + tolerance) {
      return(FALSE)
    }
  }

  return(TRUE)
}

