202|#' Sample from upper hull using inverse CDF method
203|#' @param n Number of samples
204|#' @param x Abscissae
205|#' @param h Log-density values
206|#' @param dh Derivative values
207|#' @param z Intersection points
208|#' @param domain Domain bounds
209|#' @return Vector of samples from upper hull
210|sample_upper_hull <- function(n, x, h, dh, z, domain) {
211|  n_segments <- length(x)
212|  
213|  # Compute normalization constant for each segment
214|  # Integral of exp(h[i] + dh[i]*(x - x[i])) from z[i] to z[i+1]
215|  
216|  segment_probs <- numeric(n_segments)
217|  
218|  for (i in 1:n_segments) {
219|    z_lower <- max(z[i], domain[1])
220|    z_upper <- min(z[i+1], domain[2])
221|    
222|    # Safe comparison with potentially infinite z values
223|    skip_segment <- FALSE
224|    if (is.finite(z_lower) && is.finite(z_upper)) {
225|      skip_segment <- (z_lower >= z_upper)
226|    }
227|    
228|    if (isTRUE(skip_segment)) {
229|      segment_probs[i] <- 0
230|      next
231|    }
232|    
233|    # Handle integration - including semi-infinite cases
234|    if (is.finite(dh[i]) && abs(dh[i]) < 1e-6) {
235|      # Nearly constant derivative - use direct integration
236|      if (is.finite(z_lower) && is.finite(z_upper)) {
237|        segment_probs[i] <- exp(h[i]) * (z_upper - z_lower)
238|      } else {
239|        segment_probs[i] <- 0  # Can't integrate constant over infinite domain
240|      }
241|    } else {
242|      # Integration: exp(h[i] - dh[i]*x[i]) * integral(exp(dh[i]*x))
243|      # Handle semi-infinite bounds
244|      
245|      # Compute exp(dh[i] * z) at boundaries, handling Inf
246|      if (is.finite(z_upper)) {
247|        exp_upper <- exp(dh[i] * z_upper)
248|      } else {
249|        # z_upper = Inf
250|        if (is.finite(dh[i]) && dh[i] < 0) {
251|          exp_upper <- 0  # exp(-Inf) = 0
252|        } else {
253|          exp_upper <- Inf  # Non-integrable
254|        }
255|      }
256|      
