input.script:
cd /app && Rscript -e "
# Check if formal test suite exists
if (file.exists('tests.R')) {
  cat('Found tests.R, running formal test suite...\n\n')
  source('tests.R')
} else if (file.exists('test_ars.R')) {
  cat('Found test_ars.R, running formal test suite...\n\n')
  source('test_ars.R')
} else {
  cat('No formal test file found. Checking for testthat tests...\n')
  if (dir.exists('tests')) {
    list.files('tests', recursive=TRUE, full.names=TRUE)
  } else {
    cat('No tests directory. Running basic validation instead.\n\n')
    source('ars.R')

    cat('=== Basic Validation Suite ===\n')

    # Test log-concavity check
    cat('\\n1. Testing log-concavity detection:\n')
    tryCatch({
      # Should fail - not log-concave
      ars(100, function(x) ifelse(x > 0, 1/x, -Inf), c(0, 10))
      cat('   FAIL: Did not detect non-log-concave function\n')
    }, error = function(e) {
      cat('   PASS: Correctly rejected non-log-concave function\n')
    })

    # Test vectorization
    cat('\\n2. Testing vectorization requirement:\n')
    non_vec_func <- function(x) {
      if (length(x) > 1) stop('Not vectorized')
      dnorm(x, log=TRUE)
    }
    tryCatch({
      ars(10, non_vec_func, c(-Inf, Inf))
      cat('   FAIL: Did not detect non-vectorized function\n')
    }, error = function(e) {
      cat('   PASS: Correctly detected non-vectorized function\n')
    })

    # Test boundary handling
    cat('\\n3. Testing boundary conditions:\n')
    samp_bounded <- ars(500, function(x) ifelse(x > 0 & x < 1, dbeta(x, 2, 2, log=TRUE), -Inf), c(0, 1))
    if (all(samp_bounded > 0 & samp_bounded < 1)) {
      cat('   PASS: All samples within bounds [0,1]\n')
    } else {
      cat('   FAIL: Some samples outside bounds\n')
    }

    # Test large sample generation
    cat('\\n4. Testing large sample generation:\n')
    start <- Sys.time()
    large_samp <- ars(10000, function(x) dnorm(x, log=TRUE), c(-Inf, Inf))
    elapsed <- as.numeric(Sys.time() - start, units='secs')
    cat('   Generated', length(large_samp), 'samples in', round(elapsed, 2), 'seconds\n')
    if (length(large_samp) == 10000 && elapsed < 10) {
      cat('   PASS: Efficient large sample generation\n')
    }

    cat('\\n=== Validation Complete ===\n')
  }
}
" 2>&1

